pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(uint256 seed) internal {
        address owner;
        try c.Owner() returns (address __r) { owner = __r; } catch { return; }
        bool callerIsOwner = (owner == address(this));
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        assertTrue(callerIsOwner == !reverted);
    }

    function testFuzz_run(uint256 seed) public {
        _run(seed);
    }

    receive() external payable {}
}
